def availability(statuses):
    if not statuses: return None
    return sum(s < 500 for s in statuses) / len(statuses)

def deduplicate(events):
    seen = set()
    result = []
    for event in events:
        if event['id'] not in seen:
            seen.add(event['id'])
            result.append(event)
    return result
